/**
 * useDeepLink — reads the URL once per app boot and puts the app where the
 * link asked: `?sector=X&spot=Y` pre-selects sector + spot, and `/guia`
 * (or the older `#guia/...`) opens the guide.
 *
 * When a share link generated by SpotPopup is
 * opened, the recipient lands on the correct sector with the spot popup
 * already open. URL params are stripped after use so the address bar
 * stays clean and refreshes don't re-trigger.
 */
import { useEffect } from 'react';
import { useSectorStore } from '../store/sectorStore';
import { useSpotStore } from '../store/spotStore';
import { useUIStore } from '../store/uiStore';
import { SECTORS } from '../config/sectors';
import { getSpotsForSector } from '../config/spots';
import { parseGuideTarget } from '../config/guideRoute';

/** Open the favourite spot in its own zone; nothing if there is none or it no longer exists. */
function openFavorite(): void {
  const fav = useSpotStore.getState().favoriteSpotId;
  if (!fav) return;
  const owner = SECTORS.find((s) => getSpotsForSector(s.id).some((sp) => sp.id === fav))?.id;
  if (!owner) return;
  if (owner !== useSectorStore.getState().activeSector.id) useSectorStore.getState().switchSector(owner);
  // Same small delay as a shared link: the sector switch commits first (it closes any open card)
  setTimeout(() => useSpotStore.getState().selectSpot(fav), 250);
}

export function useDeepLink(): void {
  useEffect(() => {
    if (typeof window === 'undefined') return;

    // The guide is checked FIRST and outside the early return below: a link to
    // /guia carries no sector and no spot, so anything gated on those params
    // would never see it. The modal reads the same URL to pick its section.
    const guide = parseGuideTarget(window.location.pathname, window.location.hash);
    if (guide.open) useUIStore.getState().setGuideOpen(true);

    const params = new URLSearchParams(window.location.search);
    const sectorParam = params.get('sector');
    const spotParam = params.get('spot');

    // `?bienvenida` asks the welcome questions again, for whoever already answered (or did the old tour):
    // to try it, or to set the app again. No favourite opens under it: the questions go first.
    if (params.has('bienvenida')) {
      useUIStore.setState({ onboardingCompleted: false, onboardingStep: null });
      const url = new URL(window.location.href);
      url.searchParams.delete('bienvenida');
      window.history.replaceState({}, '', url.toString());
      return;
    }

    if (!sectorParam && !spotParam) {
      // No link to follow: the app opens on the favourite spot, if there is one (chosen in the welcome
      // assistant or with the star of its card). The store said «auto-flyto on load» and nothing did it.
      if (!guide.open) openFavorite();
      return;
    }

    if (sectorParam && SECTORS.some((s) => s.id === sectorParam)) {
      useSectorStore.getState().switchSector(sectorParam);
    }

    if (spotParam) {
      // Resolve the spot against every sector, not just the one in the URL:
      // `?spot=` may come without `?sector=` (hand-written or legacy links), or
      // with one that doesn't own it. Whoever actually has the spot wins —
      // otherwise it silently fails to open.
      const owner = SECTORS.find((s) =>
        getSpotsForSector(s.id).some((sp) => sp.id === spotParam),
      )?.id;
      if (owner) {
        if (owner !== useSectorStore.getState().activeSector.id) {
          useSectorStore.getState().switchSector(owner);
        }
        // Small delay so the sector switch fully commits before opening the
        // popup (spotStore.selectSpot needs the new sector's spots loaded).
        setTimeout(() => {
          useSpotStore.getState().selectSpot(spotParam);
        }, 250);
      }
    }

    // Strip the params so refresh doesn't re-trigger and the URL stays clean.
    const url = new URL(window.location.href);
    url.searchParams.delete('sector');
    url.searchParams.delete('spot');
    window.history.replaceState({}, '', url.toString());
  }, []); // intentional: run ONCE on mount
}
